39	        true,
40	      );
41	    }
42	    for (const priority of ISSUE_PRIORITIES) {
43	      expect(
44	        createIssueSchema.safeParse(createInput({ priority })).success,
45	        priority,
46	      ).toBe(true);
47	    }
48	  });
