/** Direct live sub-issues of `issueId`, oldest first (creation time, then number). */
export async function listChildIssues(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.parentId, issueId),
        livePredicate(issues.archivedAt, {}),
      ),
    )
    .orderBy(issues.createdAt, issues.number)
    .all();

  const labels = await listLabelsForIssues(orgId, rows.map((row) => row.id as IssueId));
  return rows.map((row) => toIssue(row, (labels[row.id] ?? []).map((l) => l.id)));
}

/**
 * Every descendant of `issueId`, at any depth and regardless of archive
 * status, shallowest level first. Depth and cascade-archive checks need the
 * full tree — an already-archived node's still-live children must still be
 * reachable — so this does not filter on `archived_at` the way a list view
 * would.
 */
export async function listDescendants(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const result: Issue[] = [];
  let frontier: readonly IssueId[] = [issueId];

  while (frontier.length > 0) {
    const rows = getDb()
      .select()
      .from(issues)
      .where(
        and(orgPredicate(issues.orgId, orgId), inArray(issues.parentId, [...frontier])),
      )
      .orderBy(issues.createdAt, issues.number)
      .all();

    if (rows.length === 0) break;

    const labels = await listLabelsForIssues(orgId, rows.map((row) => row.id as IssueId));
    const mapped = rows.map((row) =>
      toIssue(row, (labels[row.id] ?? []).map((l) => l.id)),
    );
    result.push(...mapped);
    frontier = mapped.map((issue) => issue.id);
  }

  return result;
}

export async function setIssueParent(
  orgId: OrgId,
  issueId: IssueId,
  parentId: IssueId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ parentId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  return toIssue(row);
}

