}

/** Counts over every live issue below `issueId`, at any depth. */
export async function getIssueRollup(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const descendants = (await issueRepo.listDescendants(orgId, issueId)).filter(
    (descendant) => descendant.archivedAt === null,
  );
  const closed = descendants.filter((descendant) =>
    CLOSED_ISSUE_STATUSES.includes(descendant.status),
  ).length;

  return { total: descendants.length, open: descendants.length - closed, closed };
