/**
 * Tells `issue`'s direct parent's assignee once its last open sub-issue is
 * closed. Only fires when the parent exists, is live and has an assignee —
 * and only the direct parent is ever considered, not grandparents.
 */
async function notifyParentIfSubIssuesCompleted(
  orgId: OrgId,
  issue: Issue,
  actorId: UserId | null,
): Promise<void> {
  if (issue.parentId === null) return;

  const parent = await issueRepo.findIssueById(orgId, issue.parentId);
  if (parent === null || parent.archivedAt !== null || parent.assigneeId === null) {
    return;
  }

  const descendants = await issueRepo.listDescendants(orgId, parent.id);
  const stillOpenBelow = descendants.some(
