57	  assertOrgScope(actor, input.orgId);
58	
59	  const project = requireFound(
60	    await projectRepo.findProjectById(input.orgId, input.projectId),
61	    "Project",
62	    input.projectId,
63	  );
64	  assertNotArchived("Project", project.id, project);
65	  assertCan(actor, "issue:create", projectResource(project));
66	
67	  let newIssueId: IssueId | undefined;
68	  if (input.parentId !== null) {
69	    const parent = requireFound(
70	      await issueRepo.findIssueById(input.orgId, input.parentId),
71	      "Issue",
72	      input.parentId,
73	    );
74	    if (parent.projectId !== input.projectId) {
75	      throw new NotFoundError("Issue", input.parentId);
76	    }
77	    assertNotArchived("Issue", parent.id, parent);
78	
79	    newIssueId = newId() as IssueId;
