436	/** The level of `issue` in its tree: 0 for a root issue. */
437	async function levelOf(orgId: OrgId, issue: Issue): Promise<number> {
438	  let level = 0;
439	  let cursor = issue.parentId;
440	
441	  while (cursor !== null) {
442	    const ancestor = await issueRepo.findIssueById(orgId, cursor);
443	    if (ancestor === null) break;
444	    level += 1;
445	    cursor = ancestor.parentId;
446	  }
447	
448	  return level;
449	}
450	
451	/** Throws when `issueId` is `parent` or one of `parent`'s own ancestors. */
452	async function assertNoCycle(
453	  orgId: OrgId,
454	  issueId: IssueId,
455	  parent: Issue,
456	): Promise<void> {
457	  let cursor: IssueId | null = parent.id;
458	
459	  while (cursor !== null) {
460	    if (cursor === issueId) {
461	      throw new IssueHierarchyError(issueId, "cycle");
462	    }
463	    const node = await issueRepo.findIssueById(orgId, cursor);
464	    cursor = node?.parentId ?? null;
465	  }
466	}
467	
468	/** Levels below `rootId` its deepest descendant sits at; 0 with none. */
469	function maxRelativeDepth(rootId: IssueId, descendants: readonly Issue[]): number {
470	  const childrenByParent = new Map<IssueId, IssueId[]>();
471	  for (const issue of descendants) {
472	    if (issue.parentId === null) continue;
473	    const bucket = childrenByParent.get(issue.parentId) ?? [];
474	    bucket.push(issue.id);
475	    childrenByParent.set(issue.parentId, bucket);
476	  }
477	
478	  let frontier: readonly IssueId[] = [rootId];
479	  let depth = 0;
480	
481	  for (;;) {
482	    const next = frontier.flatMap((id) => childrenByParent.get(id) ?? []);
483	    if (next.length === 0) return depth;
484	    depth += 1;
485	    frontier = next;
486	  }
487	}
