/**
 * Sub-issues: placing/moving an issue under a parent, listing direct
 * sub-issues, the roll-up, cascade archiving and the `sub_issues_completed`
 * completion notice.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { MAX_SUB_ISSUE_DEPTH } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { IssueHierarchyError } from "@/lib/issue-hierarchy";
import { NotFoundError } from "@/server/services/_support";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as issueService from "@/server/services/issue-service";
import { listNotifications } from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("subissues");
});

afterAll(() => {
  cleanup();
});

async function create(
  overrides: Partial<{ title: string; assigneeId: Tenant["userIds"]["member"] | null; parentId: Issue["id"] | null }> = {},
): Promise<Issue> {
  return issueService.createIssue(tenant.actors.member, {
    ...issueInput(tenant.org.id, tenant.project.id, overrides),
    parentId: overrides.parentId ?? null,
  });
}

describe("services/issue-service — setIssueParent", () => {
  it("places an issue under a parent of the same project, announcing issue.updated", async () => {
    const parent = await create({ title: "Epic" });
    const child = await create({ title: "Task under epic" });

    const received: unknown[] = [];
    const off = subscribe("issue.updated", (payload) => {
      received.push(payload);
    });

    try {
      const moved = await issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: parent.id,
      });

      expect(moved.parentId).toBe(parent.id);
      expect(received).toHaveLength(1);
      expect(received[0]).toMatchObject({
        issueId: child.id,
        changedFields: ["parentId"],
      });
    } finally {
      off();
    }
  });

  it("is a no-op (no event) when the parent does not actually change", async () => {
    const parent = await create({ title: "Epic 2" });
    const child = await create({ title: "Task 2" });
    await issueService.setIssueParent(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child.id,
      parentId: parent.id,
    });

    const received: unknown[] = [];
    const off = subscribe("issue.updated", (payload) => received.push(payload));
    try {
      await issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: parent.id,
      });
      expect(received).toHaveLength(0);
    } finally {
      off();
    }
  });

  it("roots an issue again by setting the parent to null", async () => {
    const parent = await create({ title: "Epic 3" });
    const child = await create({ title: "Task 3" });
    await issueService.setIssueParent(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child.id,
      parentId: parent.id,
    });

    const rooted = await issueService.setIssueParent(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child.id,
      parentId: null,
    });
    expect(rooted.parentId).toBeNull();
  });

  it("refuses a parent from another project with NotFoundError", async () => {
    const otherProject = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Other project",
      slug: "other-project",
      key: "OTH",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    const foreignParent = await issueService.createIssue(tenant.actors.member, {
      ...issueInput(tenant.org.id, otherProject.id, { title: "Foreign parent" }),
      parentId: null,
    });
    const child = await create({ title: "Task 4" });

    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: foreignParent.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses an archived parent with AlreadyArchivedError", async () => {
    const parent = await create({ title: "Archived parent" });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, parent.id);
    const child = await create({ title: "Task 5" });

    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: parent.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("refuses moving an archived issue", async () => {
    const issue = await create({ title: "To archive then move" });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
    const parent = await create({ title: "Would-be parent" });

    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        parentId: parent.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("refuses placing an issue under itself (cycle)", async () => {
    const issue = await create({ title: "Self parent" });

    const error: unknown = await issueService
      .setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        parentId: issue.id,
      })
      .catch((caught: unknown) => caught);

    expect(error).toBeInstanceOf(IssueHierarchyError);
    expect((error as IssueHierarchyError).reason).toBe("cycle");
  });

  it("refuses placing an issue under one of its own sub-issues (cycle)", async () => {
    const root = await create({ title: "Root for cycle" });
    const child = await create({ title: "Child for cycle" });
    await issueService.setIssueParent(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child.id,
      parentId: root.id,
    });

    const error: unknown = await issueService
      .setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: root.id,
        parentId: child.id,
      })
      .catch((caught: unknown) => caught);

    expect(error).toBeInstanceOf(IssueHierarchyError);
    expect((error as IssueHierarchyError).reason).toBe("cycle");
  });

  it("refuses a move that would push a descendant past MAX_SUB_ISSUE_DEPTH", async () => {
    // Build a chain down to the maximum allowed depth.
    let cursor = await create({ title: "Chain root" });
    for (let level = 1; level <= MAX_SUB_ISSUE_DEPTH; level += 1) {
      const next = await create({ title: `Chain level ${level}` });
      await issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: next.id,
        parentId: cursor.id,
      });
      cursor = next;
    }
    // `cursor` now sits at level MAX_SUB_ISSUE_DEPTH.

    const separate = await create({ title: "Separate issue to move" });
    const error: unknown = await issueService
      .setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: separate.id,
        parentId: cursor.id,
      })
      .catch((caught: unknown) => caught);

    expect(error).toBeInstanceOf(IssueHierarchyError);
    expect((error as IssueHierarchyError).reason).toBe("too_deep");
  });

  it("judges a move by its deepest descendant, not just the issue itself", async () => {
    // parent sits one level below root, so a 2-level subtree moved under it
    // would land its deepest descendant at root+3 — still within bounds...
    const root = await create({ title: "Depth root" });
    const mid = await create({ title: "Depth mid" });
    await issueService.setIssueParent(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: mid.id,
      parentId: root.id,
    });

    const subtreeRoot = await create({ title: "Subtree root" });
    const subtreeChild = await create({ title: "Subtree child" });
    await issueService.setIssueParent(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: subtreeChild.id,
      parentId: subtreeRoot.id,
    });

    // mid is at level 1; subtreeRoot+subtreeChild moving under mid would put
    // subtreeChild at level 1 + 1(subtreeRoot) + 1(subtreeChild) = 3 == MAX.
    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: subtreeRoot.id,
        parentId: mid.id,
      }),
    ).resolves.toMatchObject({ parentId: mid.id });

    // Moving the already-deep subtree one level deeper now overflows.
    const oneMore = await create({ title: "One level too many" });
    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: oneMore.id,
        parentId: subtreeChild.id,
      }),
    ).rejects.toBeInstanceOf(IssueHierarchyError);
  });

  it("refuses creating an issue whose parent is already at the maximum depth", async () => {
    let cursor = await create({ title: "Create-chain root" });
    for (let level = 1; level <= MAX_SUB_ISSUE_DEPTH; level += 1) {
      const next = await create({ title: `Create-chain level ${level}`, parentId: cursor.id });
      cursor = next;
    }
    // cursor is now at level MAX_SUB_ISSUE_DEPTH; one more child is too deep.
    await expect(
      issueService.createIssue(tenant.actors.member, {
        ...issueInput(tenant.org.id, tenant.project.id, { title: "Too deep at birth" }),
        parentId: cursor.id,
      }),
    ).rejects.toBeInstanceOf(IssueHierarchyError);
  });

  it("refuses creation entirely (no row written) when the parent is archived", async () => {
    const parent = await create({ title: "Archived at birth" });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, parent.id);

    await expect(
      issueService.createIssue(tenant.actors.member, {
        ...issueInput(tenant.org.id, tenant.project.id, { title: "Should not exist" }),
        parentId: parent.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    const page = await issueService.listIssues(tenant.actors.owner, {
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
      query: "Should not exist",
    });
    expect(page.items).toHaveLength(0);
  });

  it("maps a cross-tenant setIssueParent to tenant_scope_violation", async () => {
    const other = await createTenant("subissues-other");
    const issue = await create({ title: "North issue" });

    const error: unknown = await issueService
      .setIssueParent(other.actors.owner, {
        orgId: tenant.org.id,
        issueId: issue.id,
        parentId: null,
      })
      .catch((caught: unknown) => caught);
    expect(error).toBeInstanceOf(TenantScopeError);
  });
});

describe("services/issue-service — listSubIssues and getIssueRollup", () => {
  it("lists only the direct, live sub-issues, oldest first", async () => {
    const parent = await create({ title: "Rollup parent" });
    const first = await create({ title: "First child", parentId: parent.id });
    const second = await create({ title: "Second child", parentId: parent.id });
    const archivedChild = await create({ title: "Archived child", parentId: parent.id });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archivedChild.id);

    // A grandchild must not show up in the direct listing.
    await create({ title: "Grandchild", parentId: first.id });

    const children = await issueService.listSubIssues(
      tenant.actors.owner,
      tenant.org.id,
      parent.id,
    );

    expect(children.map((c) => c.id)).toEqual([first.id, second.id]);
  });

  it("rolls up counts over every live descendant at any depth", async () => {
    const parent = await create({ title: "Deep rollup parent" });
    const child = await create({ title: "Deep rollup child", parentId: parent.id });
    const grandchild1 = await create({ title: "Grandchild open", parentId: child.id });
    const grandchild2 = await create({ title: "Grandchild closed", parentId: child.id });
    const grandchild3 = await create({ title: "Grandchild archived", parentId: child.id });

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: grandchild2.id,
      status: "done",
    });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, grandchild3.id);

    const rollup = await issueService.getIssueRollup(
      tenant.actors.owner,
      tenant.org.id,
      parent.id,
    );

    // child + grandchild1 (open) + grandchild2 (closed); grandchild3 excluded (archived).
    expect(rollup).toEqual({ total: 3, open: 2, closed: 1 });
    void grandchild1;
  });

  it("refuses listSubIssues and getIssueRollup across tenants", async () => {
    const other = await createTenant("subissues-rollup-other");
    const parent = await create({ title: "Scoped rollup parent" });

    await expect(
      issueService.listSubIssues(other.actors.owner, tenant.org.id, parent.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      issueService.getIssueRollup(other.actors.owner, tenant.org.id, parent.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

describe("services/issue-service — archiveIssue cascades to sub-issues", () => {
  it("archives every live descendant, each with its own issue.archived event", async () => {
    const root = await create({ title: "Cascade root" });
    const child = await create({ title: "Cascade child", parentId: root.id });
    const grandchild = await create({ title: "Cascade grandchild", parentId: child.id });
    const alreadyArchived = await create({ title: "Cascade pre-archived", parentId: child.id });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, alreadyArchived.id);
    const preArchivedAt = (
      await issueRepo.findIssueById(tenant.org.id, alreadyArchived.id)
    )?.archivedAt;

    const received: unknown[] = [];
    const off = subscribe("issue.archived", (payload) => received.push(payload));

    try {
      await issueService.archiveIssue(tenant.actors.member, tenant.org.id, root.id);

      const archivedIds = received.map((p) => (p as { issueId: string }).issueId);
      expect(new Set(archivedIds)).toEqual(
        new Set([root.id, child.id, grandchild.id]),
      );
      expect(archivedIds).toHaveLength(3);

      const untouchedRow = await issueRepo.findIssueById(tenant.org.id, alreadyArchived.id);
      expect(untouchedRow?.archivedAt).toBe(preArchivedAt);
    } finally {
      off();
    }
  });
});

describe("services/notification-service — sub_issues_completed", () => {
  it("tells the parent's assignee once the last open sub-issue closes", async () => {
    const parent = await issueService.createIssue(tenant.actors.member, {
      ...issueInput(tenant.org.id, tenant.project.id, { title: "Owned epic" }),
      parentId: null,
    });
    await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: parent.id,
      assigneeId: tenant.userIds.owner,
    });

    const child1 = await create({ title: "Sub A", parentId: parent.id });
    const child2 = await create({ title: "Sub B", parentId: parent.id });

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child1.id,
      status: "done",
    });

    const afterFirst = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      kind: ["sub_issues_completed"],
      limit: 25,
      cursor: null,
    });
    expect(afterFirst.items).toHaveLength(0);

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child2.id,
      status: "canceled",
    });

    const afterSecond = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      kind: ["sub_issues_completed"],
      limit: 25,
      cursor: null,
    });
    expect(afterSecond.items).toHaveLength(1);
  });

  it("does not notify when a sub-issue is moved away rather than closed", async () => {
    const parent = await issueService.createIssue(tenant.actors.member, {
      ...issueInput(tenant.org.id, tenant.project.id, { title: "Owned epic 2" }),
      parentId: null,
    });
    await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: parent.id,
      assigneeId: tenant.userIds.owner,
    });
    const child = await create({ title: "Sub to move away", parentId: parent.id });

    await issueService.setIssueParent(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child.id,
      parentId: null,
    });

    const page = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      kind: ["sub_issues_completed"],
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(0);
  });

  it("does not notify the actor about their own closing action", async () => {
    const parent = await issueService.createIssue(tenant.actors.member, {
      ...issueInput(tenant.org.id, tenant.project.id, { title: "Self-closer epic" }),
      parentId: null,
    });
    await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: parent.id,
      assigneeId: tenant.userIds.member,
    });
    const child = await create({ title: "Sub closed by its own assignee's actor", parentId: parent.id });

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child.id,
      status: "done",
    });

    const page = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      unreadOnly: false,
      kind: ["sub_issues_completed"],
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(0);
  });

  it("fires again after reopening and re-closing the last sub-issue", async () => {
    const parent = await issueService.createIssue(tenant.actors.member, {
      ...issueInput(tenant.org.id, tenant.project.id, { title: "Reopen epic" }),
      parentId: null,
    });
    await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: parent.id,
      assigneeId: tenant.userIds.owner,
    });
    const child = await create({ title: "Reopen sub", parentId: parent.id });

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child.id,
      status: "done",
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child.id,
      status: "todo",
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child.id,
      status: "done",
    });

    const page = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      kind: ["sub_issues_completed"],
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(2);
  });

  it("notifies when the last open sub-issue is archived while still open", async () => {
    const parent = await issueService.createIssue(tenant.actors.member, {
      ...issueInput(tenant.org.id, tenant.project.id, { title: "Archive-close epic" }),
      parentId: null,
    });
    await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: parent.id,
      assigneeId: tenant.userIds.owner,
    });
    const child = await create({ title: "Archive-close sub", parentId: parent.id });

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, child.id);

    const page = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      kind: ["sub_issues_completed"],
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(1);
  });

  it("does not notify when the parent has no assignee", async () => {
    const parent = await create({ title: "Unassigned epic" });
    const child = await create({ title: "Sub of unassigned epic", parentId: parent.id });

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child.id,
      status: "done",
    });

    // No assignee means nobody to notify; nothing should be recorded for
    // anyone in the tenant as a result of this specific change.
    const ownerPage = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      kind: ["sub_issues_completed"],
      limit: 25,
      cursor: null,
    });
    expect(ownerPage.total).toBe(0);
  });
});

