describe("services/notification-service — sub_issues_completed", () => {
  /** Each case gets its own tenant so notification counts never cross tests. */
  async function setUp(slug: string) {
    const scoped = await createTenant(slug);
    const parent = await issueService.createIssue(scoped.actors.member, {
      ...issueInput(scoped.org.id, scoped.project.id, { title: "Epic" }),
      parentId: null,
    });
    return { scoped, parent };
  }

  async function subIssuesCompletedFor(
    scoped: Tenant,
    recipientId: Tenant["userIds"]["owner"],
  ) {
    return listNotifications(scoped.actors.owner, {
      orgId: scoped.org.id,
      recipientId,
      unreadOnly: false,
      kind: ["sub_issues_completed"],
      limit: 25,
      cursor: null,
    });
  }

  it("tells the parent's assignee once the last open sub-issue closes", async () => {
    const { scoped, parent } = await setUp("subissues-notify-last");
    await issueService.assignIssue(scoped.actors.member, {
      orgId: scoped.org.id,
      issueId: parent.id,
      assigneeId: scoped.userIds.owner,
    });

    const child1 = await issueService.createIssue(scoped.actors.member, {
      ...issueInput(scoped.org.id, scoped.project.id, { title: "Sub A" }),
      parentId: parent.id,
    });
    const child2 = await issueService.createIssue(scoped.actors.member, {
      ...issueInput(scoped.org.id, scoped.project.id, { title: "Sub B" }),
      parentId: parent.id,
    });

    await issueService.changeIssueStatus(scoped.actors.member, {
      orgId: scoped.org.id,
      issueId: child1.id,
      status: "done",
    });
    expect((await subIssuesCompletedFor(scoped, scoped.userIds.owner)).items).toHaveLength(0);

    await issueService.changeIssueStatus(scoped.actors.member, {
      orgId: scoped.org.id,
      issueId: child2.id,
      status: "canceled",
    });
    expect((await subIssuesCompletedFor(scoped, scoped.userIds.owner)).items).toHaveLength(1);
  });

  it("does not notify when a sub-issue is moved away rather than closed", async () => {
    const { scoped, parent } = await setUp("subissues-notify-moved");
    await issueService.assignIssue(scoped.actors.member, {
      orgId: scoped.org.id,
      issueId: parent.id,
      assigneeId: scoped.userIds.owner,
    });
    const child = await issueService.createIssue(scoped.actors.member, {
      ...issueInput(scoped.org.id, scoped.project.id, { title: "Sub to move away" }),
      parentId: parent.id,
    });

    await issueService.setIssueParent(scoped.actors.member, {
      orgId: scoped.org.id,
      issueId: child.id,
      parentId: null,
    });

    expect((await subIssuesCompletedFor(scoped, scoped.userIds.owner)).items).toHaveLength(0);
  });

  it("does not notify the actor about their own closing action", async () => {
    const { scoped, parent } = await setUp("subissues-notify-self");
    await issueService.assignIssue(scoped.actors.member, {
      orgId: scoped.org.id,
      issueId: parent.id,
      assigneeId: scoped.userIds.member,
    });
    const child = await issueService.createIssue(scoped.actors.member, {
      ...issueInput(scoped.org.id, scoped.project.id, { title: "Sub closed by its assignee" }),
      parentId: parent.id,
    });

    await issueService.changeIssueStatus(scoped.actors.member, {
      orgId: scoped.org.id,
      issueId: child.id,
      status: "done",
    });

    expect((await subIssuesCompletedFor(scoped, scoped.userIds.member)).items).toHaveLength(0);
  });

  it("fires again after reopening and re-closing the last sub-issue", async () => {
    const { scoped, parent } = await setUp("subissues-notify-reopen");
    await issueService.assignIssue(scoped.actors.member, {
      orgId: scoped.org.id,
      issueId: parent.id,
      assigneeId: scoped.userIds.owner,
    });
    const child = await issueService.createIssue(scoped.actors.member, {
      ...issueInput(scoped.org.id, scoped.project.id, { title: "Reopen sub" }),
      parentId: parent.id,
    });

    await issueService.changeIssueStatus(scoped.actors.member, {
      orgId: scoped.org.id,
      issueId: child.id,
      status: "done",
    });
    await issueService.changeIssueStatus(scoped.actors.member, {
      orgId: scoped.org.id,
      issueId: child.id,
      status: "todo",
    });
    await issueService.changeIssueStatus(scoped.actors.member, {
      orgId: scoped.org.id,
      issueId: child.id,
      status: "done",
    });

    expect((await subIssuesCompletedFor(scoped, scoped.userIds.owner)).items).toHaveLength(2);
  });

  it("notifies when the last open sub-issue is archived while still open", async () => {
    const { scoped, parent } = await setUp("subissues-notify-archive");
    await issueService.assignIssue(scoped.actors.member, {
      orgId: scoped.org.id,
      issueId: parent.id,
      assigneeId: scoped.userIds.owner,
    });
    const child = await issueService.createIssue(scoped.actors.member, {
      ...issueInput(scoped.org.id, scoped.project.id, { title: "Archive-close sub" }),
      parentId: parent.id,
    });

    await issueService.archiveIssue(scoped.actors.member, scoped.org.id, child.id);

    expect((await subIssuesCompletedFor(scoped, scoped.userIds.owner)).items).toHaveLength(1);
  });

  it("does not notify when the parent has no assignee", async () => {
    const { scoped, parent } = await setUp("subissues-notify-unassigned");
    const child = await issueService.createIssue(scoped.actors.member, {
      ...issueInput(scoped.org.id, scoped.project.id, { title: "Sub of unassigned epic" }),
      parentId: parent.id,
    });

    await issueService.changeIssueStatus(scoped.actors.member, {
      orgId: scoped.org.id,
      issueId: child.id,
      status: "done",
    });

    for (const role of ["owner", "admin", "member", "viewer"] as const) {
      const page = await subIssuesCompletedFor(scoped, scoped.userIds[role]);
      expect(page.total).toBe(0);
    }
  });

  it("does not notify when an already-closed sub-issue changes to another closed status", async () => {
    const { scoped, parent } = await setUp("subissues-notify-closed-closed");
    await issueService.assignIssue(scoped.actors.member, {
      orgId: scoped.org.id,
      issueId: parent.id,
      assigneeId: scoped.userIds.owner,
    });
    const child = await issueService.createIssue(scoped.actors.member, {
      ...issueInput(scoped.org.id, scoped.project.id, { title: "Closed-to-closed sub" }),
      parentId: parent.id,
    });

    await issueService.changeIssueStatus(scoped.actors.member, {
      orgId: scoped.org.id,
      issueId: child.id,
      status: "done",
    });
    expect((await subIssuesCompletedFor(scoped, scoped.userIds.owner)).items).toHaveLength(1);

    // done -> canceled is closed-to-closed: must not re-fire the notice.
    await issueService.changeIssueStatus(scoped.actors.member, {
      orgId: scoped.org.id,
      issueId: child.id,
      status: "canceled",
    });
    expect((await subIssuesCompletedFor(scoped, scoped.userIds.owner)).items).toHaveLength(1);
  });
});

