1	/**
2	 * The fan-out hub: one domain event becomes in-app rows, an email draft and/or a digest entry, filtered by each recipient's preferences.
3	 *
4	 * Must call (do not reimplement): assertCan, assertOrgScope, isEnabled, subscribe
5	 */
6	import { subscribe } from "@/lib/event-bus";
7	import { isEnabled } from "@/lib/feature-flags";
8	import { assertCan } from "@/lib/permissions";
9	import { assertOrgScope } from "@/lib/tenant";
10	import * as issueRepo from "@/server/repositories/issue-repository";
11	import * as notificationRepo from "@/server/repositories/notification-repository";
12	import * as orgRepo from "@/server/repositories/organization-repository";
13	import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
14	import { toIsoTimestamp } from "@/types/common";
15	import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
16	import { notificationResource, requireFound } from "./_support";
17	import type {
18	  ListNotificationsInput,
19	  MarkNotificationReadInput,
20	  UpdateNotificationPreferenceInput,
21	} from "@/schemas/notification";
22	import type { OrgId, Page, UserId } from "@/types/common";
23	import type { FlagContext } from "@/types/feature-flag";
24	import type { Issue } from "@/types/issue";
25	import type { Actor } from "@/types/member";
26	import type {
27	  Notification,
28	  NotificationChannel,
29	  NotificationKind,
30	  NotificationPreference,
31	} from "@/types/notification";
32	
33	export type NotificationPayload = {
34	  title: string;
35	  body: string;
36	  href: string;
37	  actorId: UserId | null;
38	};
39	
40	/** Channels used when a recipient has never touched their preferences. */
41	const DEFAULT_CHANNELS: readonly NotificationChannel[] = ["in_app", "email"];
42	
43	/**
44	 * Writes one notification row per recipient, each with the channel set that
45	 * recipient's preferences allow. A recipient who has muted every channel is
46	 * skipped entirely rather than given a row nobody will ever see.
47	 */
48	export async function notify(
49	  orgId: OrgId,
50	  kind: NotificationKind,
51	  recipients: readonly UserId[],
52	  payload: NotificationPayload,
53	): Promise<readonly Notification[]> {
54	  if (recipients.length === 0) return [];
55	
56	  const org = await orgRepo.findOrgById(orgId);
57	  const flags: FlagContext = {
58	    orgId,
59	    userId: payload.actorId,
60	    plan: org?.plan ?? "free",
61	    role: null,
62	    overrides: org?.settings.enabledFlagOverrides,
63	  };
64	
65	  const rows = [];
66	
67	  for (const recipientId of new Set(recipients)) {
68	    if (recipientId === payload.actorId) continue;
69	
70	    const preference = await preferenceRepo.getPreference(
71	      orgId,
72	      recipientId,
73	      kind,
74	    );
75	    const channels = resolveChannels(preference, flags);
76	    if (channels.length === 0) continue;
77	
78	    rows.push({
79	      orgId,
80	      recipientId,
81	      kind,
82	      title: payload.title,
83	      body: payload.body,
84	      href: payload.href,
85	      actorId: payload.actorId,
86	      channels,
87	    });
88	  }
89	
90	  return notificationRepo.insertNotifications(orgId, rows);
91	}
92	
93	export async function listNotifications(
94	  actor: Actor,
95	  input: ListNotificationsInput,
96	): Promise<Page<Notification>> {
97	  assertOrgScope(actor, input.orgId);
98	  assertCan(
99	    actor,
100	    "notification:read",
101	    notificationResource(input.orgId, input.recipientId),
102	  );
103	  return notificationRepo.listNotifications(input);
104	}
105	
106	export async function markRead(
107	  actor: Actor,
108	  input: MarkNotificationReadInput,
109	): Promise<Notification> {
110	  assertOrgScope(actor, input.orgId);
111	  assertCan(
112	    actor,
113	    "notification:manage",
114	    notificationResource(input.orgId, actor.userId),
115	  );
116	  return notificationRepo.markRead(
117	    input.orgId,
118	    input.notificationId,
119	    toIsoTimestamp(new Date()),
120	  );
121	}
122	
123	export async function markAllRead(
124	  actor: Actor,
125	  orgId: OrgId,
126	): Promise<number> {
127	  assertOrgScope(actor, orgId);
128	  assertCan(
129	    actor,
130	    "notification:manage",
131	    notificationResource(orgId, actor.userId),
132	  );
133	  return notificationRepo.markAllRead(
134	    orgId,
135	    actor.userId,
136	    toIsoTimestamp(new Date()),
137	  );
138	}
139	
140	export async function updatePreference(
141	  actor: Actor,
142	  input: UpdateNotificationPreferenceInput,
143	): Promise<NotificationPreference> {
144	  assertOrgScope(actor, input.orgId);
145	  assertCan(
146	    actor,
147	    "notification:manage",
148	    notificationResource(input.orgId, input.userId),
149	  );
150	  return preferenceRepo.upsertPreference(input);
151	}
152	
153	/**
154	 * Turns a stored preference into the channels one notification will use.
155	 * `digestOnly` suppresses the immediate email but keeps the in-app row, and
156	 * the email channel additionally requires the org's `digest_email` plan flag.
157	 */
158	export function resolveChannels(
159	  preference: NotificationPreference | null,
160	  flags: FlagContext,
161	): readonly NotificationChannel[] {
162	  if (preference === null) return DEFAULT_CHANNELS;
163	
164	  const channels: NotificationChannel[] = [];
165	  if (preference.inApp) channels.push("in_app");
166	
167	  const emailAllowed =
168	    preference.email &&
169	    (!preference.digestOnly || isEnabled("digest_email", flags));
170	
171	  if (emailAllowed) channels.push("email");
172	  return channels;
173	}
174	
175	/**
176	 * The bus wiring. Attached at module load rather than from `event-registry`
177	 * because the fan-out has no other public entry point — importing this module
178	 * is what makes an org start receiving notifications.
179	 */
180	let registered = false;
181	
182	function registerFanOut(): void {
183	  if (registered) return;
184	  registered = true;
185	
186	  subscribe("issue.assigned", async (payload) => {
187	    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
188	      title: "You were assigned an issue",
189	      body: `Issue ${payload.issueId} is now yours`,
190	      href: `/issues/${payload.issueId}`,
191	      actorId: payload.actorId,
192	    });
193	  });
